function MaidCoffeeEventDojo:__init()
    self.completedNum = 0
    self.refreshSeconds = 0
    self.leftSeconds = 0
    self.events = { }
end

---FillVo
---@param row TableML.TableFileRow
function MaidCoffeeEventDojo:Fill(jsonData)
    jsonData = checkTable(jsonData)
    for key, value in pairs(jsonData) do
        --只更新自己关心的数据
        if isSet(jsonData, key) and table.haskey(self, key) then
            self[key] = value
            if key == "refreshSeconds" then
                self:StartTimer()
            end
        end
    end
end

function MaidCoffeeEventDojo:Events()
    return self.events
end

function MaidCoffeeEventDojo:UpdateEventStatus(eventId,status)
    if self.events[eventId] then
        self.events[eventId].status = status
    end
end

function MaidCoffeeEventDojo:RemoveEvent(eventId)
    for i, v in pairs(self.events) do
        if v.eventId == eventId then
            self.events[i] = nil
            break
        end
    end
end

function MaidCoffeeEventDojo:UpdateRefreshSeconds(time)
    self.refreshSeconds = time
    self:StartTimer()
end

function MaidCoffeeEventDojo:StartTimer()
    self:RemoveTimer()
    if self.refreshSeconds > 0 then
        self.timer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count, id)
            if count <= 0 then
                self.refreshSeconds = -1
                CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.timer)
                local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
                Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeRefreshGuestEvents)
                self.timer = nil
            end
        end, self.refreshSeconds + 1, false, true)
    end
end

function MaidCoffeeEventDojo:GetRefreshTime()
    return self.refreshSeconds
end

function MaidCoffeeEventDojo:RemoveTimer()
    if self.timer then
        CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.timer)
        self.timer = nil
    end
end

function MaidCoffeeEventDojo:__delete()
    self.incompleteNum = nil
    self.dailyLimit = nil
    self.events = nil
end

return MaidCoffeeEventDojo